{"type":"javascript","code":"// 《雨夜·顶层》剧本杀GM：状态机 + HTML案件看板
const FILE = "case_state.json";
const DASH = "case_dashboard.html";
const TRUE_CULPRIT = "陈默";
const MAX_ROUNDS = 5;
const SUSPECTS = [
  { name: "苏晚晴", role: "妻子 · 前画廊主理人", motive: "婚姻破裂，正筹备离婚" },
  { name: "陈默", role: "副总裁 · 12年合伙人", motive: "当日与林知骁有商业争执" },
  { name: "何雨", role: "私人秘书 · 服务10年", motive: "年终奖承诺被推翻" }
];
const TRUTH = "副总裁陈默挪用公司资金八千万，被林知骁发现并准备举报。21:05他将氰化物倒入林的威士忌，21:10离开；21:15他返回书房取走装赃款的U盘，21:16离开。何雨在21:10目睹有人离开书房，智能家居记录到21:15书房门开合一次——两条证据击穿了他『当晚没有再回去』的谎言。";

const cmd = String((input && input.command) || "");

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}
async function load() {
  try { return JSON.parse(await $read(FILE)); } catch (e) { return null; }
}
async function must() {
  const s = await load();
  if (!s) throw new Error("游戏尚未初始化，请先调用 case_gm(init)");
  return s;
}
function save(s) { $write(FILE, JSON.stringify(s, null, 2)); }
function fresh() {
  return {
    phase: "investigation",
    round: 1,
    max_rounds: MAX_ROUNDS,
    asked: { "苏晚晴": false, "陈默": false, "何雨": false },
    clues: [],
    suspicion: { "苏晚晴": 40, "陈默": 55, "何雨": 40 },
    accused: null,
    result: null,
    log: ["《雨夜·顶层》调查阶段开始（第1/5轮）"]
  };
}
function barColor(v) { return v >= 80 ? "#ff4d6d" : v >= 60 ? "#ffb703" : "#4cc9f0"; }
const CSS = `*{margin:0;padding:0;box-sizing:border-box}
body{background:#0b0f1a;color:#dfe7f5;font-family:"PingFang SC","Microsoft YaHei","Noto Sans SC",sans-serif;padding:24px;background-image:radial-gradient(circle at 15% 0%,rgba(76,201,240,.10),transparent 45%),radial-gradient(circle at 85% 100%,rgba(255,77,109,.08),transparent 45%)}
.wrap{max-width:880px;margin:0 auto}
h1{font-size:28px;letter-spacing:6px;color:#eaf6ff;text-shadow:0 0 18px rgba(76,201,240,.55)}
.sub{color:#7d8ca6;margin-top:6px;font-size:13px;letter-spacing:1px}
.badge{display:inline-block;margin-top:14px;padding:6px 16px;border:1px solid #4cc9f0;color:#4cc9f0;border-radius:999px;font-size:14px;letter-spacing:2px;background:rgba(76,201,240,.08)}
.settle{margin-top:22px;border-radius:14px;padding:18px;border:1px solid}
.settle.win{border-color:#2dd4a7;background:rgba(45,212,167,.08)}
.settle.lose{border-color:#ff4d6d;background:rgba(255,77,109,.08)}
.settle-title{font-size:20px;font-weight:800;letter-spacing:2px;margin-bottom:10px}
.settle.win .settle-title{color:#2dd4a7}
.settle.lose .settle-title{color:#ff4d6d}
.settle div{font-size:13.5px;line-height:1.7}
.truth{margin-top:10px;color:#dfe7f5}
.score{margin-top:10px;color:#8fa3c8}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:22px}
.card{background:rgba(20,28,48,.85);border:1px solid #223055;border-radius:12px;padding:16px}
.card.accused{border-color:#ff4d6d;box-shadow:0 0 16px rgba(255,77,109,.35)}
.card-head{display:flex;justify-content:space-between;align-items:baseline}
.name{font-size:19px;font-weight:700}
.susp{font-size:13px;font-weight:700}
.role{color:#8fa3c8;font-size:12px;margin-top:4px}
.motive{color:#b7c4dc;font-size:12px;margin-top:8px;line-height:1.5}
.bar{height:8px;background:#161f38;border-radius:99px;margin-top:10px;overflow:hidden}
.fill{height:100%;border-radius:99px}
.meta{margin-top:8px;font-size:12px;color:#7d8ca6;min-height:16px}
h2{margin-top:26px;font-size:16px;letter-spacing:3px;color:#9fd8ef;border-left:3px solid #4cc9f0;padding-left:10px}
.clues{margin-top:12px;list-style:none}
.clues li{background:rgba(20,28,48,.7);border:1px solid #1d2a4a;border-radius:10px;padding:10px 12px;margin-bottom:8px;font-size:13.5px;line-height:1.6}
.cid{color:#4cc9f0;font-weight:700;margin-right:6px}
.csrc{color:#7d8ca6;font-size:12px}
.empty{color:#66748f;font-style:italic}
.timeline{margin-top:12px}
.tl{display:flex;gap:12px;padding:7px 0;border-bottom:1px dashed #1d2a4a;font-size:13px}
.tlt{color:#ffb703;min-width:110px;font-family:ui-monospace,monospace}
.tld{color:#b7c4dc}
.tips{margin-top:26px;color:#66748f;font-size:12px;line-height:1.9;border-top:1px solid #1d2a4a;padding-top:12px}
@media(max-width:720px){.grid{grid-template-columns:1fr}}`;

function buildHtml(s) {
  const phaseLabel = s.phase === "investigation"
    ? "调查阶段 · 第 " + s.round + "/" + s.max_rounds + " 轮"
    : (s.result === "win" ? "已结算 · 查案成功" : "已结算 · 查案失败");
  const cards = SUSPECTS.map(function (p) {
    const v = s.suspicion[p.name] || 0;
    const color = barColor(v);
    const meta = [];
    if (s.phase === "investigation" && s.asked[p.name]) meta.push("本轮已作答");
    if (s.accused === p.name) meta.push("【被指认】");
    if (s.phase === "settlement" && p.name === TRUE_CULPRIT) meta.push("★ 真凶");
    return '<div class="card ' + (s.accused === p.name ? "accused" : "") + '">'
      + '<div class="card-head"><span class="name">' + esc(p.name) + '</span><span class="susp" style="color:' + color + '">嫌疑 ' + v + '</span></div>'
      + '<div class="role">' + esc(p.role) + '</div>'
      + '<div class="motive">公开动机：' + esc(p.motive) + '</div>'
      + '<div class="bar"><div class="fill" style="width:' + v + '%;background:' + color + '"></div></div>'
      + '<div class="meta">' + meta.join(" · ") + '</div>'
      + '</div>';
  }).join("");
  const clues = s.clues.length
    ? s.clues.map(function (c) {
        return '<li><span class="cid">#' + c.id + '</span>' + esc(c.text) + ' <span class="csrc">— 来自 ' + esc(c.source) + ' · 第' + c.round + '轮</span></li>';
      }).join("")
    : '<li class="empty">尚未记录线索 —— 从三个人的嘴里把它挖出来。</li>';
  const settle = s.phase === "settlement"
    ? '<div class="settle ' + s.result + '">'
      + '<div class="settle-title">' + (s.result === "win" ? "✔ 指认命中" : "✘ 指认落空") + '</div>'
      + '<div>玩家指认：<b>' + esc(s.accused) + '</b>'
      + (s.result === "lose" ? ' &nbsp;|&nbsp; 真凶是：<b>' + esc(TRUE_CULPRIT) + '</b>' : "")
      + '</div>'
      + '<div class="truth">真相：' + TRUTH + '</div>'
      + '<div class="score">共记录线索 ' + s.clues.length + ' 条 &nbsp;·&nbsp; 结果：' + (s.result === "win" ? "胜利" : "失败") + '</div>'
      + '</div>'
    : "";
  const TIMELINE = [
    ["15:00", "苏晚晴与林知骁电话激烈争执（内容不详）"],
    ["19:00", "晚餐，全员在客厅"],
    ["20:00-20:30", "四人在客厅看电视"],
    ["21:00-21:30", "各去各的：苏晚晴称阳台抽烟 / 陈默称去过书房被拒、离开后未再返回 / 何雨称厨房泡茶"],
    ["21:30", "林知骁死于书房，桌上威士忌杯检出氰化物"]
  ].map(function (t) {
    return '<div class="tl"><span class="tlt">' + esc(t[0]) + '</span><span class="tld">' + esc(t[1]) + '</span></div>';
  }).join("");
  return '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>雨夜·顶层 - 案件看板</title>\n<style>' + CSS + '</style>\n</head>\n<body>\n<div class="wrap">\n<h1>雨夜 · 顶层</h1>\n<div class="sub">现代都市悬疑剧本杀 · 星澜阁27层 · 雨夜</div>\n<div class="badge">' + phaseLabel + '</div>\n' + settle + '\n<div class="grid">' + cards + '</div>\n<h2>线索板</h2>\n<ul class="clues">' + clues + '</ul>\n<h2>公开时间线</h2>\n<div class="timeline">' + TIMELINE + '</div>\n<div class="tips">玩家操作：向嫌疑人提问（每人每轮限答1问） · 说「下一轮」进入下一轮 · 说「指认：姓名」进行结算。<br>本看板由主持人通过 case_gm 技能维护。</div>\n</div>\n</body>\n</html>';
}

let out;
if (cmd === "init") {
  const s = fresh();
  save(s);
  out = { message: "游戏已初始化。请调用 case_gm(dashboard) 并用 file_display 展示看板", state: s };
} else if (cmd === "status") {
  out = { state: await must() };
} else if (cmd === "mark_asked") {
  const s = await must();
  const n = String(input.name || "");
  if (!(n in s.asked)) throw new Error("未知角色：" + n + "（须为 苏晚晴/陈默/何雨）");
  if (s.phase === "investigation") { s.asked[n] = true; save(s); }
  out = { message: n + " 已标记为本轮已作答", state: s };
} else if (cmd === "next_round") {
  const s = await must();
  if (s.phase !== "investigation") throw new Error("游戏已结算，不能再推进轮次");
  if (s.round >= s.max_rounds) {
    out = { message: "调查轮次已用完（5/5）！请让玩家说「指认：姓名」进行结算", state: s };
  } else {
    s.round += 1;
    s.asked = { "苏晚晴": false, "陈默": false, "何雨": false };
    s.log.push("进入第 " + s.round + "/" + s.max_rounds + " 轮");
    save(s);
    out = { message: "已进入第 " + s.round + "/" + s.max_rounds + " 轮，本轮三人可重新作答", state: s };
  }
} else if (cmd === "add_clue") {
  const s = await must();
  const text = String(input.text || "").trim();
  if (!text) throw new Error("缺少线索内容 text");
  if (s.clues.some(function (c) { return c.text === text; })) {
    out = { message: "该线索已记录过，不重复记录", state: s };
  } else {
    s.clues.push({ id: s.clues.length + 1, text: text, source: String(input.source || "未知"), round: s.round });
    s.log.push("新线索 #" + s.clues.length + "：" + text);
    save(s);
    out = { message: "线索已记录（#" + s.clues.length + "）", state: s };
  }
} else if (cmd === "set_suspicion") {
  const s = await must();
  const n = String(input.name || "");
  if (!(n in s.suspicion)) throw new Error("未知嫌疑人：" + n + "（须为 苏晚晴/陈默/何雨）");
  const v = Math.max(0, Math.min(100, Math.round(Number(input.value) || 0)));
  s.suspicion[n] = v;
  save(s);
  out = { message: n + " 的嫌疑值已设为 " + v, state: s };
} else if (cmd === "accuse") {
  const s = await must();
  if (s.phase !== "investigation") throw new Error("游戏已结算，不能再次指认");
  const n = String(input.name || "").trim();
  if (!(n in s.suspicion)) throw new Error("不能指认「" + n + "」，须为三名嫌疑人之一");
  s.accused = n;
  s.phase = "settlement";
  s.result = n === TRUE_CULPRIT ? "win" : "lose";
  s.log.push("结算：指认 " + n + "，结果 " + (s.result === "win" ? "胜利" : "失败"));
  save(s);
  out = {
    result: s.result,
    correct: s.result === "win",
    accused: n,
    true_culprit: TRUE_CULPRIT,
    clues_found: s.clues.length,
    message: s.result === "win"
      ? "玩家指认正确，胜利！请公布完整真相并展示最终看板"
      : "玩家指认错误，失败。请公布真凶并展示最终看板",
    note: "请调用 case_gm(dashboard) 并用 file_display 展示最终看板"
  };
} else if (cmd === "dashboard") {
  const s = await must();
  $write(DASH, buildHtml(s));
  out = { path: DASH, message: "看板已生成，请用 file_display 展示该路径" };
} else {
  throw new Error("未知命令：" + cmd + "。可用：init / status / mark_asked / next_round / add_clue / set_suspicion / accuse / dashboard");
}
result = out;"}
